[CmdletBinding(SupportsShouldProcess)] param([string]$InstallDir=(Join-Path $env:LOCALAPPDATA 'Programs\Expedient AI Bridges'),[switch]$NoShortcuts,[switch]$NoStart,[switch]$Uninstall)
$ErrorActionPreference='Stop';$source=Split-Path -Parent $PSScriptRoot;$data=Join-Path $env:LOCALAPPDATA 'ExpedientAIBridges'
if($Uninstall){& (Join-Path $InstallDir 'ExpedientBridges.exe') stop 2>$null;if($PSCmdlet.ShouldProcess($InstallDir,'Remove immutable program')){Remove-Item $InstallDir -Recurse -Force};return}
if($PSCmdlet.ShouldProcess($InstallDir,'Install Expedient AI Bridges')){New-Item $InstallDir -ItemType Directory -Force|Out-Null;Copy-Item (Join-Path $source '*') $InstallDir -Recurse -Force -Exclude 'install.ps1';New-Item $data -ItemType Directory -Force|Out-Null;$config=Join-Path $data 'config.env';if(!(Test-Path $config)){Copy-Item (Join-Path $InstallDir 'config.env.example') $config};$sid=[System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value;& icacls $data /inheritance:r /grant:r "*$sid:(OI)(CI)F" '*S-1-5-18:(OI)(CI)F'|Out-Null}
if(!$NoShortcuts){$start=Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs';$shell=New-Object -ComObject WScript.Shell;$shortcut=$shell.CreateShortcut((Join-Path $start 'Expedient AI Bridges.lnk'));$shortcut.TargetPath=Join-Path $InstallDir 'ExpedientBridges.exe';$shortcut.Arguments='start';$shortcut.Save()}
if(!$NoStart){& (Join-Path $InstallDir 'ExpedientBridges.exe') migrate;& (Join-Path $InstallDir 'ExpedientBridges.exe') start}
